function studentPerformance(panel,rows){const by={};rows.forEach(x=>{const k=x.term+" / "+x.session;if(!by[k])by[k]=[];by[k].push(Number(x.total_score||0))});const data=Object.entries(by).map(([term,vals])=>[term,vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*100)/100:0]);panel.innerHTML='<section class="dashboard-card"><div class="section-head"><div><p class="section-label">Academic Analysis</p><h2>My Performance</h2></div></div>'+(data.length?table(["Term / Session","Average /100"],data.map(x=>'<tr><td>'+esc(x[0])+'</td><td><strong>'+x[1]+'</strong></td></tr>').join("")):'<p class="muted">Performance will appear after your results are available.</p>')+'</section>'}
